var app={}
var windowWidth=0;var windowHeight=0;var contentHeight=0;var $window=null;var $title=null;var $root=null;function setRoot(rootKey,path,callback){$(function(){$window=$(window);$title=$("title");$root=$(rootKey);$window.resize(function(){windowWidth=$window.width();windowHeight=$window.height();contentHeight=windowHeight-54;});lazyComponent($root,path);$root.on('click','.core-link',function(){var $that=$(this);lazyComponent($root,$(this).attr('url'),$that.attr("data"));});$window.resize();if(callback){callback();}});}
function lazyComponent($container,path,data){var title,url;var match=app.routers.find(x=>x.path==path);if(match){url=match.components;var title=match.title;if(title.indexOf('${name}')>-1){title=title.replace('${name}',app.name);}
$title.text(title);if(url.indexOf('?')>-1){url=url+'&v='+app.version;}else{url=url+'?v='+app.version;}
request(url,function(content){$container.html(content);var props={router:match,data:data};eval('if(isExitsFunction("onLoad")){$(function () {onLoad('+JSON.stringify(props)+')})};');toTop($container);},'html');}else{console.error('路由匹配失败:'+path);}}
function toTop($element){$element.animate({scrollTop:0},1);}
function request(url,callback,type){$.get(url,function(data){if(callback!=null){callback(data);}},type);}
function calcHeight(vh){return vh/100*windowHeight;}
function calcWidth(vw){return vw/100*windowWidth;}
function newId(){return randomStr(10)+getUnixTime();}
function randomStr(length){var str=Math.random().toString(36).substring(2);while(str.length<length){str=Math.random().toString(36).substring(2)}
return str.substring(0,length);}
function getUnixTime(){return new Date().getTime();}
function isExitsFunction(funcName){try{if(typeof(eval(funcName))=="function"){return true;}}catch(e){}
return false;}
function lock($elm,message){var oldText=$elm.text();$elm.addClass('lock').attr('old-text',oldText).text(message).attr('disabled',true);}
function unlock($elm){$elm.removeClass('lock').text($elm.attr('old-text')).removeAttr('disabled');}
function getUrlParam(name){var reg=new RegExp("(^|&)"+name+"=([^&]*)(&|$)");var r=window.location.search.substr(1).match(reg);if(r!=null){return decodeURIComponent(unescape(r[2]));}
return null;}
function loadLink(url){var href=url+'?v='+app.version;var $matchs=$("link[href='"+href+"']");if($matchs.length>0){$matchs.remove();}
var link=document.createElement('link');link.rel="stylesheet";link.type="text/css";link.href=href;document.getElementsByTagName("head")[0].appendChild(link);}
function loadScript(url,callback){var src=url+'?v='+app.version;var $matchs=$("script[src='"+src+"']");if($matchs.length>0){$matchs.remove();}
var script=document.createElement('script'),fn=callback||function(){};script.type='text/javascript';script.src=src;document.getElementsByTagName('head')[0].appendChild(script);script.onload=function(){fn();};}